PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PreviousLevel : INT := 0;
END_VAR

// Check if the current level is different from the previous level
IF Level <> PreviousLevel THEN
    // Update the previous level
    PreviousLevel := Level;

    // Implement hysteresis logic for PumpIn
    IF Level <= LowLimit THEN
        PumpIn := TRUE;
    ELSIF Level >= HighLimit THEN
        PumpIn := FALSE;
    ELSE
        PumpIn := FALSE;
    END_IF;

    // Ensure PumpIn is off if the level is at or above HighLimit
    IF Level >= HighLimit THEN
        PumpIn := FALSE;
    END_IF;

    // Always open the outlet valve if the level is at or above HighLimit
    IF Level >= HighLimit THEN
        ValveOut := TRUE;
    ELSE
        ValveOut := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LastLevel : INT := 0;
    PumpTimer : TON;
END_VAR

// Check if the current level is different from the last level
IF Level <> LastLevel THEN
    // Reset the pump timer when the level changes
    PumpTimer(IN := FALSE);
END_IF;

// Update the last recorded level
LastLevel := Level;

// Determine the state of the pump based on the hysteresis logic
IF Level <= 10 THEN
    PumpIn := TRUE;
    PumpTimer(IN := TRUE, PT := T#5s);
ELSIF Level >= 90 OR PumpTimer.Q THEN
    PumpIn := FALSE;
END_IF;

// Always ensure the outlet valve opens at or above the high limit
IF Level >= 90 THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

END_PROGRAM

