PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    previous_Level : INT := 0;
    PumpTimer : TON;
END_VAR

// Check if the current level is different from the previous level
IF Level <> previous_Level THEN
    // Reset the pump timer when the level changes
    PumpTimer(IN := FALSE);
END_IF;

// Check if the level is at or above the high limit (90%)
IF Level >= 90 THEN
    // Turn off the pump and open the outlet valve
    PumpIn := FALSE;
    ValveOut := TRUE;

    // Start the pump timer for safety (ensure pump does not run at high level)
    PumpTimer(IN := TRUE, PT := T#5s);
ELSE
    // Check if the pump timer has elapsed
    IF PumpTimer.Q THEN
        // If the timer has elapsed, check the level again
        IF Level <= 85 THEN
            // Turn on the pump and close the outlet valve if level is below 85%
            PumpIn := TRUE;
            ValveOut := FALSE;
        ELSE
            // Otherwise, keep the pump off and open the outlet valve
            PumpIn := FALSE;
            ValveOut := TRUE;
        END_IF;
    ELSE
        // If the pump timer has not elapsed, check the level directly
        IF Level <= 10 THEN
            // Turn on the pump and close the outlet valve if level is below 10%
            PumpIn := TRUE;
            ValveOut := FALSE;
        ELSE
            // Otherwise, keep the pump off and open the outlet valve
            PumpIn := FALSE;
            ValveOut := TRUE;
        END_IF;
    END_IF;
END_IF;

// Update the previous level
previous_Level := Level;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

// Check for overflow condition first
IF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Implement hysteresis logic
IF NOT PumpTimer.Q AND Level > LowLimit THEN
    PumpTimer(IN := TRUE, PT := T#1s);
END_IF;

IF PumpTimer.Q AND Level <= LowLimit THEN
    PumpTimer(IN := FALSE);
END_IF;

PumpIn := PumpIn AND NOT ValveOut; // Ensure pump does not run if valve is open due to high level
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    previous_Level : INT := 0;
    PumpTimer : TON;
END_VAR

// Check if the level has changed significantly
IF ABS(Level - previous_Level) >= 5 THEN
    previous_Level := Level;

    // Handle high limit safety condition
    IF Level >= 90 THEN
        PumpIn := FALSE;
        ValveOut := TRUE;
    ELSE
        // Implement hysteresis for normal operation
        IF Level <= 10 THEN
            PumpIn := TRUE;
            ValveOut := FALSE;
        ELSIF Level >= 85 AND Level < 90 THEN
            PumpIn := FALSE;
            ValveOut := FALSE;
        ELSE
            PumpIn := FALSE;
            ValveOut := TRUE;
        END_IF;
    END_IF;
END_IF;

END_PROGRAM

