// Check for safety condition: never run PumpIn when Level >= HighLimit
IF Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF;

// Implement hysteresis logic for maintaining the tank level
IF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Optionally, update LastLevel for future reference if needed
LastLevel := Level;
END_PROGRAM

