    DoorA_Latched := TRUE;
    DoorB_Latched := FALSE;
ELSIF PriorityTimer_B.Q THEN
    DoorA_Latched := FALSE;
    DoorB_Latched := TRUE;
END_IF;

IF NOT OpenA_Cmd THEN
    DoorA_Latched := FALSE;
END_IF;

IF NOT OpenB_Cmd THEN
    DoorB_Latched := FALSE;
END_IF;
END_PROGRAM

