PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    green_timer, yellow_timer, all_red_timer : TON;
END_VAR

// Define constants for timing durations
CONSTANT
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_CONSTANT

// Update the state based on the current timer status
CASE State OF
    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;

        green_timer(IN := TRUE, PT := PT_GREEN);
        IF green_timer.Q THEN
            State := 1;
        END_IF;

    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;

        yellow_timer(IN := TRUE, PT := PT_YELLOW);
        IF yellow_timer.Q THEN
            State := 2;
        END_IF;

    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;

        all_red_timer(IN := TRUE, PT := PT_ALLRED);
        IF all_red_timer.Q THEN
            State := 3;
        END_IF;

    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;

        green_timer(IN := TRUE, PT := PT_GREEN);
        IF green_timer.Q THEN
            State := 4;
        END_IF;

    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;

        yellow_timer(IN := TRUE, PT := PT_YELLOW);
        IF yellow_timer.Q THEN
            State := 5;
        END_IF;

    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;

        all_red_timer(IN := TRUE, PT := PT_ALLRED);
        IF all_red_timer.Q THEN
            State := 0;
        END_IF;
END_CASE;

// Reset timers when not active
green_timer(IN := FALSE);
yellow_timer(IN := FALSE);
all_red_timer(IN := FALSE);

END_PROGRAM

PROGRAM intersection
VAR
    State : INT := 0;
    NS_G, NS_Y, NS_R : BOOL := FALSE;
    EW_G, EW_Y, EW_R : BOOL := FALSE;
    TGreen_NS, TYellow_NS, TAllRed_NS : TON;
    TGreen_EW, TYellow_EW, TAllRed_EW : TON;
END_VAR

TGreen_NS(IN := State = 0 OR State = 3, PT := T#2s);
TYellow_NS(IN := State = 1 OR State = 4, PT := T#1s);
TAllRed_NS(IN := State = 2 OR State = 5, PT := T#1s);

TGreen_EW(IN := State = 3 OR State = 0, PT := T#2s);
TYellow_EW(IN := State = 4 OR State = 1, PT := T#1s);
TAllRed_EW(IN := State = 5 OR State = 2, PT := T#1s);

NS_G := NOT NS_R AND NOT NS_Y AND TGreen_NS.Q;
NS_Y := NOT NS_R AND NOT NS_G AND TYellow_NS.Q;
NS_R := NOT NS_G AND NOT NS_Y AND TAllRed_NS.Q;

EW_G := NOT EW_R AND NOT EW_Y AND TGreen_EW.Q;
EW_Y := NOT EW_R AND NOT EW_G AND TYellow_EW.Q;
EW_R := NOT EW_G AND NOT EW_Y AND TAllRed_EW.Q;

CASE State OF
    0:
        NS_G := TRUE;
        EW_R := TRUE;
    1:
        NS_Y := TRUE;
        EW_R := TRUE;
    2:
        NS_R := TRUE;
        EW_R := TRUE;
    3:
        EW_G := TRUE;
        NS_R := TRUE;
    4:
        EW_Y := TRUE;
        NS_R := TRUE;
    5:
        EW_R := TRUE;
        NS_R := TRUE;
END_CASE;

State := (State + 1) MOD 6;
END_PROGRAM

PROGRAM intersection
VAR
    State : INT := 0;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL := FALSE;
    T_NSGreen, T_NSYellow, T_EWGreen, T_EWYellow, T_AllRed : TON;
END_VAR

T_NSGreen(IN := State = 0 OR State = 3, PT := T#2s);
T_NSYellow(IN := State = 1 OR State = 4, PT := T#1s);
T_EWGreen(IN := State = 3 OR State = 0, PT := T#2s);
T_EWYellow(IN := State = 4 OR State = 1, PT := T#1s);
T_AllRed(IN := State = 2 OR State = 5, PT := T#1s);

CASE State OF
    0: 
        NS_G := TRUE;
        EW_R := TRUE;
    1: 
        NS_Y := TRUE;
        EW_R := TRUE;
    2: 
        NS_R := TRUE;
        EW_R := TRUE;
    3: 
        EW_G := TRUE;
        NS_R := TRUE;
    4: 
        EW_Y := TRUE;
        NS_R := TRUE;
    5: 
        EW_R := TRUE;
        NS_R := TRUE;
END_CASE;

State := State + 1;
IF State > 5 THEN
    State := 0;
END_IF;

NS_G := NOT T_NSGreen.Q AND NOT T_NSYellow.Q AND NS_G;
NS_Y := NOT T_NSYellow.Q AND T_NSYellow.Q;
NS_R := NOT T_NSGreen.Q AND NOT T_NSYellow.Q AND NOT NS_G AND NOT NS_Y;
EW_G := NOT T_EWGreen.Q AND NOT T_EWYellow.Q AND EW_G;
EW_Y := NOT T_EWYellow.Q AND T_EWYellow.Q;
EW_R := NOT T_EWGreen.Q AND NOT T_EWYellow.Q AND NOT EW_G AND NOT EW_Y;
END_PROGRAM

