ELSIF State = 1 THEN
    State := 2;
ELSIF State = 2 THEN
    State := 3;
ELSIF State = 3 THEN
    State := 4;
ELSIF State = 4 THEN
    State := 5;
ELSIF State = 5 THEN
    State := 0;
END_IF;
