    DelayCompleted : BOOL;
END_VAR

VAR_CONSTANT
    PT_DELAY : TIME := T#3s;
END_VAR

Motor := FALSE;

IF NOT EStop THEN
    StartTimer(IN := StartCmd, PT := PT_DELAY);
    DelayCompleted := StartTimer.Q;

    IF DelayCompleted AND StartCmd THEN
        Motor := TRUE;
    ELSE
        Motor := FALSE;
    END_IF;
ELSE
    Motor := FALSE;
    StartTimer(IN := FALSE, PT := T#0s);
END_IF;

END_PROGRAM

PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    StartTimer : TON;
    MotorStarted : BOOL := FALSE;
END_VAR

CONSTANT
    PT_DELAY : TIME := T#3s;
END_CONSTANT

// Reset motor state if emergency stop is activated
IF NOT EStop THEN
    Motor := FALSE;
    MotorStarted := FALSE;
    StartTimer(IN := FALSE);
END_IF;

// Check if start command is held for the required delay
IF StartCmd AND EStop THEN
    StartTimer(IN := TRUE, PT := PT_DELAY);
    IF StartTimer.Q THEN
        MotorStarted := TRUE;
    END_IF;
END_IF;

// De-energize motor if start command is released or emergency stop activates
IF NOT StartCmd OR NOT EStop THEN
    Motor := FALSE;
    MotorStarted := FALSE;
    StartTimer(IN := FALSE);
END_IF;

// Hold motor energized if started
IF MotorStarted AND EStop THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    StartTimer : TON;
    StartHeld : BOOL := FALSE;
END_VAR

CONSTANT
    PT_DELAY : TIME := T#3s;
END_CONSTANT

// Update the start timer if StartCmd is TRUE and EStop is not activated
StartTimer(IN := StartCmd AND NOT EStop, PT := PT_DELAY);

// Check if the start timer has completed
IF StartTimer.Q THEN
    StartHeld := TRUE;
END_IF;

// De-energize the motor if StartCmd is FALSE or EStop is activated
Motor := StartHeld AND StartCmd AND NOT EStop;

// Reset the start held flag if StartCmd is FALSE
IF NOT StartCmd OR EStop THEN
    StartHeld := FALSE;
END_IF;

END_PROGRAM

PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    StartTimer : TON;
    StartHeld : BOOL;
END_VAR

CONSTANT
    PT_DELAY : TIME := T#3s;
END_CONSTANT

Motor := FALSE;

IF NOT EStop THEN
    StartTimer(IN := StartCmd AND NOT StartHeld, PT := PT_DELAY);
    StartHeld := StartCmd;

    IF StartTimer.Q THEN
        Motor := TRUE;
    ELSE
        Motor := FALSE;
    END_IF;
ELSE
    StartTimer(IN := FALSE, PT := PT_DELAY);
    StartHeld := FALSE;
    Motor := FALSE;
END_IF;

END_PROGRAM

PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    StartTimer : TON;
    HoldCount : INT := 0;
    MaxHoldCount : INT := 3;
END_VAR

CONSTANT
    PT_DELAY : TIME := T#3s;
END_CONSTANT

Motor := FALSE;

IF NOT EStop THEN
    IF StartCmd THEN
        StartTimer(IN := TRUE, PT := PT_DELAY);
        IF StartTimer.Q THEN
            HoldCount := HoldCount + 1;
            IF HoldCount >= MaxHoldCount THEN
                Motor := TRUE;
            END_IF;
        END_IF;
    ELSE
        HoldCount := 0;
        Motor := FALSE;
        StartTimer(IN := FALSE);
    END_IF;
END_IF;

IF NOT EStop THEN
    Motor := FALSE;
    StartTimer(IN := FALSE);
    HoldCount := 0;
END_IF;

END_PROGRAM

PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    StartTimer : TON;
    MotorEnabled : BOOL := FALSE;
END_VAR

CONSTANT
    PT_DELAY : TIME := T#3s;
END_CONSTANT

// Handle emergency stop
IF NOT EStop THEN
    Motor := FALSE;
    MotorEnabled := FALSE;
    StartTimer(IN := FALSE);
END_IF;

// Check if start command is maintained for the required delay
IF StartCmd AND MotorEnabled THEN
    Motor := TRUE;
ELSIF StartCmd AND NOT MotorEnabled THEN
    StartTimer(IN := TRUE, PT := PT_DELAY);
    IF StartTimer.Q THEN
        MotorEnabled := TRUE;
        Motor := TRUE;
    END_IF;
ELSIF NOT StartCmd AND MotorEnabled THEN
    Motor := FALSE;
    MotorEnabled := FALSE;
    StartTimer(IN := FALSE);
END_IF;

END_PROGRAM

