    T_Walk : TON;
    PT_GREEN : TIME := T#3s;
    PT_YELLOW : TIME := T#2s;
    PT_WALK : TIME := T#3s;
END_VAR

T_Green(IN := State = 0 AND PedReq, PT := PT_GREEN);
T_Yellow(IN := State = 1, PT := PT_YELLOW);
T_Walk(IN := State = 2, PT := PT_Walk);

CarGreen := State = 0 AND NOT T_Green.Q;
CarYellow := State = 1 AND NOT T_Yellow.Q;
CarRed := State <> 0 OR T_Green.Q OR T_Yellow.Q OR T_Walk.Q;
PedWalk := State = 2 AND NOT T_Walk.Q;

CASE State OF
    0: IF T_Green.Q THEN State := 1; END_IF;
    1: IF T_Yellow.Q THEN State := 2; END_IF;
    2: IF T_Walk.Q THEN State := 0; END_IF;
END_CASE;

