VAR
    State : INT := 0;
    FillTimer : TON;
    DrainTimer : TON;
    HIGH_LEVEL : INT := 90;
    LOW_LEVEL : INT := 10;
END_VAR

FillTimer(IN := Pump AND NOT EStop, PT := T#5s);
DrainTimer(IN := Valve AND NOT EStop, PT := T#5s);

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF StartCycle AND Level < HIGH_LEVEL THEN
            State := 1;
