        Pump := FALSE;
        Valve := TRUE;
        IF Level <= LOW_LEVEL OR NOT StartCycle OR EStop THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
ASSERT NOT(Pump AND Valve);
ASSERT NOT(Level >= HIGH_LEVEL AND Pump);
ASSERT NOT(Level <= LOW_LEVEL AND Valve);

