IF RH AND NOT RH_ReleaseTimer.Q THEN
    RH_ReleaseTimer(IN := TRUE, PT := T#0s);
    Armed := FALSE;
END_IF;

// Enable actuator only when both buttons are pressed and control is armed
Actuator := LH AND RH AND Armed;
