PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
END_VAR

// Detect falling edge of Demand
PrevDemand := Demand;

IF NOT EStop THEN
    // Check for falling edge of Demand
    IF NOT PrevDemand AND Demand THEN
        // Alternate lead
        Lead := 1 - Lead;
    END_IF;

    // Assign pumps based on lead status
    IF Demand THEN
        Pump1 := (Lead = 0);
        Pump2 := (Lead = 1);
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_IF;
ELSE
    // Emergency stop overrides all
    Pump1 := FALSE;
    Pump2 := FALSE;
END_IF;
END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    TmpPump1 : BOOL := FALSE;
    TmpPump2 : BOOL := FALSE;
END_VAR

PrevDemand := Demand;

IF NOT EStop THEN
    IF Demand AND NOT PrevDemand THEN
        Lead := 1 - Lead;
    END_IF;

    CASE Lead OF
        0 :
            TmpPump1 := TRUE;
            TmpPump2 := FALSE;
        1 :
            TmpPump1 := FALSE;
            TmpPump2 := TRUE;
    END_CASE;
ELSE
    TmpPump1 := FALSE;
    TmpPump2 := FALSE;
END_IF;

Pump1 := TmpPump1 AND Demand;
Pump2 := TmpPump2 AND Demand;
END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    T_EStopRelease : TON;
END_VAR

// Detect falling edge of Demand for lead change
PrevDemand := Demand;

IF NOT EStop THEN
    // Emergency stop activated, stop both pumps
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF Demand AND NOT PrevDemand THEN
        // Rising edge of Demand detected, toggle lead
        Lead := 1 - Lead;
    END_IF;

    CASE Lead OF
        0:
            Pump1 := Demand;
            Pump2 := FALSE;
        1:
            Pump1 := FALSE;
            Pump2 := Demand;
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_CASE;
END_IF;

// Reset T_EStopRelease on EStop release
T_EStopRelease(IN := NOT EStop, PT := T#0s);
IF T_EStopRelease.Q THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
END_IF;
END_PROGRAM

