END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
END_VAR

Pump1 := FALSE;
Pump2 := FALSE;

IF NOT EStop THEN
    IF Demand AND NOT PrevDemand THEN
        Lead := 1 - Lead; // Toggle lead on rising edge of demand
