PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR

VAR_OUTPUT
    Done : BOOL;
END_VAR

VAR
    Count : INT := 0;
    PrevTrigger : BOOL := FALSE;
    Target : INT := 3;
END_VAR

PrevTrigger := Trigger;

IF Reset THEN
    Count := 0;
    Done := FALSE;
ELSIF NOT PrevTrigger AND Trigger THEN
    IF Count < Target THEN
        Count := Count + 1;
    END_IF;
    IF Count >= Target THEN
        Done := TRUE;
    ELSE
        Done := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR

VAR_OUTPUT
    Done : BOOL;
END_VAR

VAR
    Count : INT := 0;
    PrevTrigger : BOOL := FALSE;
END_VAR

// Edge detection for Trigger
PrevTrigger := NOT PrevTrigger AND Trigger;

// Increment Count on rising edge of Trigger, but never exceed 3
IF PrevTrigger THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
END_IF;

// Set Done when Count reaches 3
Done := Count = 3;

// Reset Count and clear Done on Reset signal
IF Reset OR Done THEN
    Count := 0;
    Done := FALSE;
END_IF;

END_PROGRAM

